61	{
62	  // Create the 2d field.
63	  // Create xz grid.
64	  double lower[] = { -M_PI, 0.0 }, upper[] = { M_PI, 1.0 };
65	  int cells[] = { 12, 8 };
66	  struct gkyl_rect_grid grid;
67	  gkyl_rect_grid_init(&grid, 2, lower, upper, cells);
