87	  struct gkyl_array *field_dev = use_gpu ? gkyl_array_cu_dev_new(GKYL_DOUBLE, basis.num_basis, local_ext.volume)
88		                                 : gkyl_array_acquire(field);
89	  gkyl_array_copy(field_dev, field);
90	
91	  // Create deflated 1d grid, ranges, basis, and field.
92	  double deflated_lower[] = { -M_PI}, deflated_upper[] = { M_PI};
93	  int deflated_cells[] = { 12};
94	  struct gkyl_rect_grid deflated_grid;
95	  gkyl_rect_grid_init(&deflated_grid, 1, deflated_lower, deflated_upper, deflated_cells);
96	
97	  // Ranges.
98	  struct gkyl_range deflated_local, deflated_local_ext;
99	  int deflated_nghost[GKYL_MAX_CDIM] = { 1 };
100	  gkyl_create_grid_ranges(&deflated_grid, deflated_nghost, &deflated_local_ext, &deflated_local);
101	
102	  // Deflated basis function.
103	  int deflated_poly_order = 1;
104	  struct gkyl_basis deflated_basis;
105	  gkyl_cart_modal_serendip(&deflated_basis, 1, deflated_poly_order);
106	  struct gkyl_basis *deflated_basis_on_dev = use_gpu? gkyl_cart_modal_serendip_cu_dev_new(1, poly_order)
107	                                                    : gkyl_cart_modal_serendip_new(1, poly_order);
108	  
109	  // Deflated field.
110	  struct gkyl_array *deflated_field = gkyl_array_new(GKYL_DOUBLE, deflated_basis.num_basis, deflated_local_ext.volume);
111	  struct gkyl_array *deflated_field_dev = use_gpu ? gkyl_array_cu_dev_new(GKYL_DOUBLE, deflated_basis.num_basis, deflated_local_ext.volume)
112		                                          : gkyl_array_acquire(deflated_field);
113	
114	  // Create nrange and the 2d nodal array to be populated.
115	  int nodes[2] = { 1, 1 };
116	  if (poly_order == 1){
117	    for (int d=0; d<grid.ndim; ++d)
118	      nodes[d] = grid.cells[d] + 1;
119	  }
120	  if (poly_order == 2){
121	    for (int d=0; d<grid.ndim; ++d)
122	      nodes[d] = 2*(grid.cells[d]) + 1;
123	  }
124	  struct gkyl_range nrange;
125	  gkyl_range_init_from_shape(&nrange, grid.ndim, nodes);
126	  struct gkyl_array* nodal_fld = gkyl_array_new(GKYL_DOUBLE, grid.ndim, nrange.volume);
127	  struct gkyl_array* nodal_fld_dev = use_gpu ? gkyl_array_cu_dev_new(GKYL_DOUBLE, grid.ndim, nrange.volume)
128		                                     : gkyl_array_acquire(nodal_fld);
