60	void
61	test_coll_cx_d(bool use_gpu)
62	{
63	  int charge_state = 0;
64	  int poly_order = 1;
65	  int cdim = 2, vdim_vl = 3;
66	
67	  // Grids 
68	  double lower_ion[] = {-2.0,-2.0}, upper_ion[] = {2.0,2.0};
69	  int ghost_gk[] = {0, 0};
70	  int cells_gk[] = {2, 2};
71	
72	  struct gkyl_rect_grid confGrid;
73	  struct gkyl_range confRange, confRange_ext;
74	  gkyl_rect_grid_init(&confGrid, cdim, lower_ion, upper_ion, cells_gk);
75	  gkyl_create_grid_ranges(&confGrid, ghost_gk, &confRange_ext, &confRange);
76	
77	  // Basis functions.
78	  struct gkyl_basis basis;
79	  gkyl_cart_modal_serendip(&basis, cdim, poly_order);
80	
81	  // Projection updater for moments.
82	  gkyl_proj_on_basis *proj_n = gkyl_proj_on_basis_new(&confGrid, &basis,
83	    poly_order+1, 1, eval_n, NULL);
84	  gkyl_proj_on_basis *proj_T_over_m_ion = gkyl_proj_on_basis_new(&confGrid, &basis,
85	    poly_order+1, 1, eval_T_over_m_ion, NULL);
86	  gkyl_proj_on_basis *proj_T_over_m_neut = gkyl_proj_on_basis_new(&confGrid, &basis,
87	    poly_order+1, 1, eval_T_over_m_neut, NULL);
88	
89	  double vt_sq_ion_min = 1*echarge/d_ion_mass;
90	  double vt_sq_neut_min = 1*echarge/d_ion_mass;
91	  struct gkyl_dg_cx_inp cx_inp = {
92	    .cbasis = &basis,
93	    .conf_rng = &confRange,
94	    .vt_sq_ion_min = vt_sq_ion_min, 
95	    .vt_sq_neut_min = vt_sq_neut_min, 
96	    .type_ion = GKYL_ION_D,
97	  };
98	  
99	  // Coll struct.
100	  struct gkyl_dg_cx *coll_cx_up = gkyl_dg_cx_new(&cx_inp, use_gpu);;
101	
102	  struct gkyl_array *n_ion = mkarr(use_gpu, basis.num_basis, confRange.volume);
103	  struct gkyl_array *T_over_m_ion = mkarr(use_gpu, basis.num_basis, confRange.volume);
104	  struct gkyl_array *moms_ion = mkarr(use_gpu, (1+2)*basis.num_basis, confRange.volume);
105	  struct gkyl_array *n_neut = mkarr(use_gpu, basis.num_basis, confRange.volume);
106	  struct gkyl_array *T_over_m_neut = mkarr(use_gpu, basis.num_basis, confRange.volume);
107	  struct gkyl_array *moms_neut = mkarr(use_gpu, (3+2)*basis.num_basis, confRange.volume);
108	  struct gkyl_array *coef_cx = mkarr(use_gpu, basis.num_basis, confRange.volume);
109	  
110	  // Arrays necessary for prim_vars.
111	  struct gkyl_array *u_par_ion = mkarr(use_gpu, 3*basis.num_basis, confRange.volume);
112	  struct gkyl_array *b_i = mkarr(use_gpu, 3*basis.num_basis, confRange.volume);
113	  struct gkyl_array *b_x = mkarr(use_gpu, basis.num_basis, confRange.volume);
114	  struct gkyl_array *b_y = mkarr(use_gpu, basis.num_basis, confRange.volume);
115	  struct gkyl_array *b_z = mkarr(use_gpu, basis.num_basis, confRange.volume);
116	  
117	  // Project moments on basis.
118	  proj_on_basis_copy(proj_n, 0.0, &confRange, n_ion, use_gpu);
119	  proj_on_basis_copy(proj_T_over_m_ion, 0.0, &confRange, T_over_m_ion, use_gpu);
120	  gkyl_array_set_offset(moms_ion, 1.0, n_ion, 0);
121	  gkyl_array_set_offset(moms_ion, 1.0, T_over_m_ion, (1+1)*basis.num_basis);
122	
123	  proj_on_basis_copy(proj_n, 0.0, &confRange, n_neut, use_gpu);
124	  proj_on_basis_copy(proj_T_over_m_neut, 0.0, &confRange, T_over_m_neut, use_gpu);
125	  gkyl_array_set_offset(moms_neut, 1.0, n_neut, 0);
126	  gkyl_array_set_offset(moms_neut, 1.0, T_over_m_neut, (1+vdim_vl)*basis.num_basis);
127	
128	  // Project b_i.
129	  gkyl_array_set_offset(b_i, 1.0, b_x, 0);
130	  gkyl_array_set_offset(b_i, 1.0, b_y, basis.num_basis);
131	  gkyl_array_set_offset(b_i, 1.0, b_z, 2*basis.num_basis);
132	
133	  // Compute the CX reaction rate.
134	  gkyl_dg_cx_coll(coll_cx_up, moms_ion, moms_neut, u_par_ion, coef_cx, 0);    
135	
136	  struct gkyl_array *coef_cx_ho = use_gpu? mkarr(false, coef_cx->ncomp, coef_cx->size)
137	                                         : gkyl_array_acquire(coef_cx);
138	  gkyl_array_copy(coef_cx_ho, coef_cx);
139	
140	  const double *cv_cx = gkyl_array_cfetch(coef_cx_ho, gkyl_range_idx(&confRange, (int[2]) { 1, 1}));
141	
142	  // Test against predicted value.
143	  double p1_vals[] = {3.242709205939892e-14, 0.000000000000000e+00,
144			      0.000000000000000e+00, 0.000000000000000e+00};
145	  for (int i=0; i<basis.num_basis; ++i) {
146	    TEST_CHECK( gkyl_compare_double(p1_vals[i]*check_fac, cv_cx[i]*check_fac, 1e-12) );
147	    TEST_MSG( "i:%d | Expected: %.9e | Got:%.9e\n", i, p1_vals[i]*check_fac, cv_cx[i]*check_fac );
148	  }
149	
150	  gkyl_array_release(n_ion); 
151	  gkyl_array_release(T_over_m_ion); 
152	  gkyl_array_release(n_neut); 
153	  gkyl_array_release(T_over_m_neut);
154	  gkyl_array_release(moms_neut); 
155	  gkyl_array_release(moms_ion);
156	  gkyl_array_release(u_par_ion);
157	  gkyl_array_release(b_i); 
158	  gkyl_array_release(b_x); 
159	  gkyl_array_release(b_y); 
160	  gkyl_array_release(b_z);
161	  gkyl_array_release(coef_cx);
162	  gkyl_array_release(coef_cx_ho);
163	  gkyl_proj_on_basis_release(proj_n); 
164	  gkyl_proj_on_basis_release(proj_T_over_m_ion); 
165	  gkyl_proj_on_basis_release(proj_T_over_m_neut); 
166	  gkyl_dg_cx_release(coll_cx_up); 
