81	    gkyl_cart_modal_serendip(&basis, pdim, poly_order);
82	    gkyl_cart_modal_serendip(&surf_basis, pdim-1, poly_order);
83	  } else if (poly_order == 1) {
84	    /* Force hybrid basis (p=2 in velocity space). */
85	    gkyl_cart_modal_gkhybrid(&basis, cdim, vdim);
86	    gkyl_cart_modal_gkhybrid(&surf_basis, cdim-1, vdim);
87	  }
