106	      .basis = confBasis,
107	      .geo_grid = confGrid,
108	      .geo_local = confRange,
109	      .geo_local_ext = confRange_ext,
110	      .geo_global = confRange,
111	      .geo_global_ext = confRange_ext,
112	      .geo_basis = confBasis,
113	  };
114	
115	  struct gk_geometry *gk_geom = gkyl_gk_geometry_mapc2p_new(&geometry_input);
116	
117	  // Initialize gyrokinetic variables
